  fdfs_only PMc -> mat_stable PMc -> a0 = Z_to_bv 64 (p_ubeg (l_SB (lay Σ)) c i n) -> tp = Z_to_bv 64 0x777e98 ->
  ART_A Σ m -> mem_inv asegs m -> call_ok RTA Σ m sp lo -> unwind_okC m ra s0 sp ->
